(7185683, 1104427, 91496, '<td valign="top">Great colors and layering.  How did it look without all the noise.  I think it may have more feeling being smoother rather than so grainy.</td>', 'Great colors and layering.  How did it look without all the noise.  I think it may have more feeling being smoother rather than so grainy.', '2014-03-05 16:47:20.000000', NULL, 1),
(7185685, 1104837, 91496, '<td valign="top">Great pattern and interesting as a puzzle.  Seems to be too sharp and in focus to have had any motion going on.</td>', 'Great pattern and interesting as a puzzle.  Seems to be too sharp and in focus to have had any motion going on.', '2014-03-05 16:50:07.000000', NULL, 1),
