(7185726, 1104860, 174908, '<td valign="top">Yes, it fits the brief but looks like a blurred photograph rather than a deliberate attempt to be abstract.</td>', 'Yes, it fits the brief but looks like a blurred photograph rather than a deliberate attempt to be abstract.', '2014-03-05 18:05:12.000000', NULL, 1),
(7185727, 1104907, 174908, '<td valign="top">Not sure what I am looking at ... but I find the photograph appealing. I thin the convergence of lines and the additional detail helps.</td>', 'Not sure what I am looking at ... but I find the photograph appealing. I thin the convergence of lines and the additional detail helps.', '2014-03-05 18:06:13.000000', NULL, 1),
