(7187618, 1104142, 83313, '<td valign="top">I like what the slight motion blur does to give this scene an impression of depth. I don''t feel it is abstract imagery, however.</td>', 'I like what the slight motion blur does to give this scene an impression of depth. I don''t feel it is abstract imagery, however.', '2014-03-08 20:20:21.000000', NULL, 1),
(7187620, 1104851, 83313, '<td valign="top">A wonderful shot that conveys lots of motion. I''m afraid I can''t see what is abstract about it, however.</td>', 'A wonderful shot that conveys lots of motion. I''m afraid I can''t see what is abstract about it, however.', '2014-03-08 20:22:33.000000', NULL, 1),
(7187622, 1104499, 83313, '<td valign="top">An excellent example of something that is recognizable, but still abstract in it''s approach. The focus of the image is on the colors, shapes and textures, rather than the actual subject. A high vote for this one.</td>', 'An excellent example of something that is recognizable, but still abstract in it''s approach. The focus of the image is on the colors, shapes and textures, rather than the actual subject. A high vote for this one.', '2014-03-08 20:24:22.000000', NULL, 1),
(7187624, 1104828, 83313, '<td valign="top">I like this a lot, but I''m having a hard time seeing it as an abstract. It could perhaps meet some definitions of it, however. I''ll be interested to see the other comments.</td>', 'I like this a lot, but I''m having a hard time seeing it as an abstract. It could perhaps meet some definitions of it, however. I''ll be interested to see the other comments.', '2014-03-08 20:27:26.000000', NULL, 1),
