INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7189735, 1104789, 5112, '<td valign="top">Wow, Margaret, this is beautifully seen and photographed!  I love it!<br/> <br/>Added:  Ive been trying to guess the shutter speed you used for this, the tips of the little waves somewhere in between bubbles and flowing, not too fast, not too long I imagine ... faster than 1 sec, somewhere between 1 sec and 1/30?  Hopefully I''m not too far off :)<br/><br/><br/><i>Message edited by author 2014-03-14 17:05:06.</i></td>', 'Wow, Margaret, this is beautifully seen and photographed!  I love it! Added:  Ive been trying to guess the shutter speed you used for this, the tips of the little waves somewhere in between bubbles and flowing, not too fast, not too long I imagine ... faster than 1 sec, somewhere between 1 sec and 1/30?  Hopefully I''m not too far off :)', '2014-03-14 17:00:16.000000', '2014-03-14 17:05:06.000000', 0),
